module assembly_optimizer (input clk, input rst_n, input start, input [2:0] num_symbols, input [2:0] seq_length, input [2:0] sequence [0:7], input [17:0] time_table [0:2][0:2], input [1:0] result_table [0:2][0:2], output reg [19:0] min_time, output reg [1:0] result_symbol, output reg done); reg [2:0] state, state_next; reg [7:0] internal_sequence [7]; reg [2:0] local_seq_length; reg [2:0] load_counter; reg [2:0] current_length; reg [2:0] current_i; reg [2:0] current_p; reg [2:0] current_l; reg [2:0] current_m; reg [19:0] dp [7][7][3]; reg [19:0] min_time_val; reg [1:0] min_k; reg [2:0] reg_seq_length; localparam IDLE = 3'd0, LOAD_SEQ = 3'd1, INIT_DP = 3'd2, DP_OUTER = 3'd3, DP_MIDDLE = 3'd4, DP_INNER = 3'd5, DP_LM = 3'd6, FIND_RESULT = 3'd7, DONE = 3'd8; always_ff @(posedge clk) begin if (!rst_n) begin state <= IDLE; state_next <= IDLE; internal_sequence <= 8'b0; local_seq_length <= 3'b0; load_counter <= 3'b0; current_length <= 3'b0; current_i <= 3'b0; current_p <= 3'b0; current_l <= 3'b0; current_m <= 3'b0; min_time_val <= 20'd0; min_k <= 2'b00; reg_seq_length <= 3'b0; dp <= 20'd0; end else begin state <= state_next; case (state) IDLE: begin if (start) state_next = LOAD_SEQ; else state_next = IDLE; end LOAD_SEQ: begin if (load_counter == 3'b0) reg_seq_length <= seq_length; if (load_counter < reg_seq_length) begin internal_sequence[load_counter] <= sequence[load_counter]; load_counter <= load_counter + 1; state_next = LOAD_SEQ; end else begin load_counter <= 3'b0; state_next = INIT_DP; end end INIT_DP: begin state_next = DP_OUTER; end DP_OUTER: begin if (current_length < reg_seq_length) begin current_length <= current_length + 1; current_i <= 3'b0; state_next = DP_MIDDLE; end else begin state_next = FIND_RESULT; end end DP_MIDDLE: begin if (current_i < reg_seq_length - current_length) begin current_i <= current_i + 1; current_p <= current_i; state_next = DP_INNER; end else begin current_length <= current_length + 1; current_i <= 3'b0; state_next = DP_OUTER; end end DP_INNER: begin if (current_p < current_i + current_length - 1) begin current_p <= current_p + 1; state_next = DP_INNER; end else begin current_l <= 3'b0; current_m <= 3'b0; state_next = DP_LM; end end DP_LM: begin if (current_l < 3) begin if (current_m < 3) begin current_m <= current_m + 1; state_next = DP_LM; end else begin current_m <= 3'b0; current_l <= current_l + 1; state_next = DP_LM; end end else begin state_next = FIND_RESULT; end end FIND_RESULT: begin min_time_val <= dp[0][reg_seq_length-1][0]; min_k <= 0; if (dp[0][reg_seq_length-1][1] < min_time_val) begin min_time_val <= dp[0][reg_seq_length-1][1]; min_k <= 1; end if (dp[0][reg_seq_length-1][2] < min_time_val) begin min_time_val <= dp[0][reg_seq_length-1][2]; min_k <= 2; end min_time <= min_time_val; result_symbol <= min_k; done <= 1'b1; state_next = DONE; end DONE: state_next = DONE; endcase end endmodule